(async () => {
  const real = window.fetch.bind(window);
  window.fetch = (input, init) => {
    const url = typeof input === 'string' ? input : input.url;
    if (/\/respond$|\/api\/inbox/.test(url)) return new Promise(() => {});
    return real(input, init);
  };
  const [inbox, fixture] = await Promise.all([import('/src/state/inbox.ts'), import('/src/testing/inbox-fixture.ts')]);
  const now = Date.now();
  inbox.setInboxView(fixture.inboxView([
    { ...fixture.approvalRow, at: now - 2 * 60_000 },
    { ...fixture.questionRow, at: now - 20 * 60_000 },
    { ...fixture.reportRow, at: now - 3 * 60 * 60_000 },
  ]));
  inbox.openInbox();
  return true;
})()
